CREATE OR ALTER PROCEDURE [dbo].[uspMenuLine_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @MenuId UNIQUEIDENTIFIER = NULL
	, @DishId UNIQUEIDENTIFIER = NULL
	, @MealType NVARCHAR(MAX) = NULL
	, @DayOfWeek INT = NULL
	, @StandardQuantity DECIMAL(18,4) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[MenuId]
			, t.[DishId]
			, t.[MealType]
			, t.[SequenceNo]
			, t.[PortionQty]
			, t.[IsRequired]
			, t.[DayOfWeek]
			, t.[SortOrder]
			, t.[StandardQuantity]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[MenuLine] AS t
		
		WHERE 1 = 1
			AND (@MenuId IS NULL OR t.[MenuId] = @MenuId)
			AND (@DishId IS NULL OR t.[DishId] = @DishId)
			AND (ISNULL(@MealType, '') = '' OR t.[MealType] = @MealType)
			AND (@DayOfWeek IS NULL OR t.[DayOfWeek] = @DayOfWeek)
			AND (@StandardQuantity IS NULL OR t.[StandardQuantity] = @StandardQuantity)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'menuId' THEN r.[MenuId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'menuId' THEN r.[MenuId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishId' THEN r.[DishId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishId' THEN r.[DishId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'mealType' THEN r.[MealType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'mealType' THEN r.[MealType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sequenceNo' THEN r.[SequenceNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sequenceNo' THEN r.[SequenceNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'portionQty' THEN r.[PortionQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'portionQty' THEN r.[PortionQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isRequired' THEN r.[IsRequired] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isRequired' THEN r.[IsRequired] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dayOfWeek' THEN r.[DayOfWeek] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dayOfWeek' THEN r.[DayOfWeek] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sortOrder' THEN r.[SortOrder] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sortOrder' THEN r.[SortOrder] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'standardQuantity' THEN r.[StandardQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'standardQuantity' THEN r.[StandardQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
